def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n < 10:
        return 'C'
    last_own, last_opp = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')
    own_defects = sum(1 for s, _ in history if s == 'D')
    recent = history[-8:]
    recent_opp_def = sum(1 for _, o in recent if o == 'D')
    if n < 20:
        if recent_opp_def >= 4:
            return 'D'
        if last_opp == 'D' and last_own == 'C':
            return 'D'
        return 'C'
    # Retaliate proportionally then try to restore cooperation
    if recent_opp_def >= 5:
        return 'D'
    if last_opp == 'D' and last_own == 'C':
        return 'D'
    if n > 50 and recent_opp_def == 0 and own_defects > opp_defects + 3:
        # We are exploiting too much; offer cooperation
        return 'C'
    # Check if opponent is mostly cooperative
    coop_rate = (n - opp_defects) / n
    if coop_rate > 0.85 and recent_opp_def <= 1:
        # Mostly cooperate, occasionally defect for exploitation
        if n % 17 == 0:
            return 'D'
        return 'C'
    if coop_rate > 0.6:
        if last_opp == 'D':
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'
    # Opponent is hostile; defect mostly
    if last_opp == 'C' and rng.random() < 0.3:
        return 'C'
    return 'D'
